import "@flux-ui/tokens/theme.css";
import "@flux-ui/tokens/reset.css";
import "@flux-ui/tokens/presets.css";
import { Container, Field, Select, Stack, ThemeScope } from "@flux-ui/react";
import { useState } from "react";
import { createRoot } from "react-dom/client";
import Scene from "./showcase/scenes/marketing.preview.js";
function App() {
  const [mood, setMood] = useState("paper");
  return <ThemeScope theme={mood} query><Container as="main" size="full" query><Stack gap="lg" padding="md"><Field.Root><Field.Label>Application mood</Field.Label><Field.Control><Select value={mood} onChange={(event) => setMood(event.currentTarget.value)}><option value="paper">Paper</option><option value="studio">Studio</option><option value="bloom">Bloom</option><option value="terminal">Terminal</option></Select></Field.Control></Field.Root><Scene /></Stack></Container></ThemeScope>;
}
const root = document.getElementById("root");
if (root === null) throw new Error("Missing application root.");
createRoot(root).render(<App />);

