/* Original poster artwork. Typography and layout are public Flux composition. */
.campaign-poster {
  position: relative;
  overflow: hidden;
  background: var(--art-canvas);
  color: var(--art-ink);
}
.poster-foreground {
  position: relative;
  z-index: 1;
}
.poster-sculpture {
  position: absolute;
  inline-size: 19rem;
  block-size: 19rem;
  inset: auto -3rem 2rem auto;
  transform: rotate(-25deg);
  pointer-events: none;
}
.poster-sculpture > div {
  position: absolute;
  inset: 0;
  border: 2rem solid currentColor;
  border-radius: 50%;
  opacity: 0.12;
}
.poster-sculpture > div:nth-child(2) {
  transform: translate(-15%, -5%) scale(0.72);
  opacity: 0.15;
}
.poster-sculpture > div:nth-child(3) {
  transform: translate(-25%, -8%) scale(0.45);
  opacity: 0.18;
}
@container flux-layout (min-width: 48rem) {
  .poster-sculpture {
    inline-size: 23rem;
    block-size: 23rem;
    inset-inline-end: -2rem;
  }
}
@container flux-layout (max-width: 30rem) {
  .poster-sculpture {
    inline-size: 16rem;
    block-size: 16rem;
  }
}
